using System;using System.Collections.Generic;using Game.Components;using Game.Configs;using Game.Skirmish.Contracts;using Unity.Entities;using Unity.Collections;
namespace Game.Runtime {
// Semantic public UI read model. This is neither an input injection path nor native screen/hit-test evidence.
internal static class PublicCommandCatalog {
 internal sealed class RoleControl {internal string RoleId,PrefabKey;internal SkirmishRoleKind Role;internal SkirmishProducerKind Producer;internal SkirmishProductionDecision Quote;}
 internal sealed class TargetControl {internal Entity Entity;internal string StableId;internal byte Faction;internal bool Structure;internal SkirmishContactKnowledgeElement? PublicKnowledge;}
 internal sealed class View {internal bool Active;internal readonly List<SkirmishArmyDrawerSlot> Groups=new List<SkirmishArmyDrawerSlot>();internal readonly List<RoleControl> Recruitment=new List<RoleControl>();internal readonly List<TargetControl> Targets=new List<TargetControl>();internal bool HasSelectedLivingPlayerMember;internal SkirmishAriaPublicView PublicView;internal Game.UI.Contracts.UiExpandedSquadPage Page;internal Game.UI.Contracts.UiSkirmishModel UiPublicFlags;internal bool CombinedArmsField;internal SkirmishHealthReadout PlayerBaseHealth,EnemyBaseHealth;}
 // The source gateway prerequisites from SkirmishActorCommandAuthority.IsActiveOwnedActor precede any actor dispatch.
 internal static bool ActiveSession(EntityManager em,Entity session){if(!em.Exists(session)||!em.HasComponent<SkirmishExpandedSessionComponent>(session)||!em.HasComponent<SkirmishObjectiveClockComponent>(session))return false;var s=em.GetComponentData<SkirmishExpandedSessionComponent>(session);if(s.IsLegacy!=0||s.Phase!=SkirmishSessionPhase.Playing||s.SessionId.IsEmpty||em.GetComponentData<SkirmishObjectiveClockComponent>(session).Paused!=0)return false;using var q=em.CreateEntityQuery(typeof(RuntimeGameplayStateComponent));return q.IsEmptyIgnoreFilter||(q.CalculateEntityCount()==1&&q.GetSingleton<RuntimeGameplayStateComponent>().SimulationActive!=0);}
 internal static View Read(EntityManager em,Entity session,SkirmishArmyProfileConfig army){var view=new View{Active=ActiveSession(em,session)};if(!em.Exists(session)||!em.HasComponent<SkirmishExpandedSessionComponent>(session))return view;if(army==null||!em.HasComponent<SkirmishResolvedSetupRecord>(session))throw new NotSupportedException("Genuine army profile/resolved catalog metadata required");var setup=em.GetComponentObject<SkirmishResolvedSetupRecord>(session).Setup;if(setup?.RoleOverlays==null)throw new NotSupportedException("Complete authored production role catalog required");
 view.PublicView=SkirmishAriaPublicProjection.FromSession(em,session,army);view.UiPublicFlags=SourceUiPublicFlags.Read(setup,view.PublicView);using(var gameplay=em.CreateEntityQuery(typeof(RuntimeGameplayStateComponent))){view.UiPublicFlags.Paused=gameplay.CalculateEntityCount()==1&&gameplay.GetSingleton<RuntimeGameplayStateComponent>().SimulationActive==0;}view.UiPublicFlags.InfantryCount=view.PublicView.OwnInfantry;view.UiPublicFlags.PlayerDesignatedAlive=view.PublicView.PlayerDesignatedAlive;view.UiPublicFlags.EnemyDesignatedAlive=view.PublicView.EnemyDesignatedAlive;view.PlayerBaseHealth=SkirmishBaseAssaultHudProjection.ReadPlayerBase(em,session);view.EnemyBaseHealth=SkirmishBaseAssaultHudProjection.ReadEnemyBase(em,session);view.UiPublicFlags.PlayerHealth=view.PlayerBaseHealth.DisplayedCurrent;view.UiPublicFlags.EnemyHealth=view.EnemyBaseHealth.DisplayedCurrent;view.CombinedArmsField=setup.ArmyProfileId==SkirmishArmyProfileId.CombinedArms&&setup.StartPackageId==SkirmishStartPackageId.FieldBase;SourceExpandedPageProjection.TryReadPage(em,session,out view.Page);if(!view.Active)return view;SkirmishArmyDrawerProjection.Project(em,session,view.Groups);view.HasSelectedLivingPlayerMember=SkirmishArmySelectionService.HasSelectedLivingPlayerMember(em,session,0);
 var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var overlay in setup.RoleOverlays){if(string.IsNullOrEmpty(overlay.RoleId)||!seen.Add(overlay.RoleId))throw new NotSupportedException("Missing/duplicate authored role control ID");if(!army.Allows(overlay.RoleId))continue;string key=null;if(setup.Forces!=null)foreach(var f in setup.Forces)if(f.RoleKind==overlay.RoleKind&&!string.IsNullOrEmpty(f.RuntimePrefabKey)){key=f.RuntimePrefabKey;break;}if(key==null)key=SkirmishRoleCatalogConfig.RuntimePrefabKey(overlay.RoleKind);view.Recruitment.Add(new RoleControl{RoleId=overlay.RoleId,Role=overlay.RoleKind,PrefabKey=key,Producer=overlay.Producer,Quote=SkirmishProductionService.EvaluateQueue(em,session,overlay.RoleId,1,army,1)});}
 var id=em.GetComponentData<SkirmishExpandedSessionComponent>(session).SessionId;using var query=em.CreateEntityQuery(typeof(SkirmishAttemptOwnedComponent));using var entities=query.ToEntityArray(Allocator.Temp);foreach(var e in entities){var own=em.GetComponentData<SkirmishAttemptOwnedComponent>(e);if(!own.SessionId.Equals(id)||own.FactionId==1||!SkirmishArmyGroupSystem.IsAlive(em,e)||!SkirmishFogService.IsVisibleToFaction(em,e,1))continue;bool known=SkirmishFogService.TryGetKnowledge(em,e,1,out var knowledge);view.Targets.Add(new TargetControl{Entity=e,StableId=own.StableObjectId.ToString(),Faction=own.FactionId,Structure=own.IsStructure!=0,PublicKnowledge=known?knowledge:(SkirmishContactKnowledgeElement?)null});}
 return view;}
}
